```go
package main

import (
	"fmt"
	"log"
	"net"
	"sync"
	"time"
)

// DNSForwarder handles incoming DNS requests, caches results, and forwards to upstreams.
type DNSForwarder struct {
	cache   map[string][]net.IP
	mu      sync.RWMutex
	upstreams []string
}

// NewDNSForwarder creates a new instance with the specified upstream DNS servers.
func NewDNSForwarder(upstreams []string) *DNSForwarder {
	return &DNSForwarder{
		cache:   make(map[string][]net.IP),
		upstreams: upstreams,
	}
}

// Resolve attempts to resolve a hostname.
// 1. Checks the cache first.
// 2. If not cached, queries upstreams.
// 3. Stores the result in the cache.
func (d *DNSForwarder) Resolve(host string) ([]net.IP, error) {
	// 1. Check Cache (Read Lock)
	d.mu.RLock()
	if ips, ok := d.cache[host]; ok {
		d.mu.RUnlock()
		return ips, nil
	}
	d.mu.RUnlock()

	// 2. Query Upstreams
	var allIPs []net.IP
	var err error

	// Try each upstream until one succeeds
	for _, upstream := range d.upstreams {
		ips, err := net.LookupIP(host)
		if err == nil && len(ips) > 0 {
			allIPs = ips
			break
		}
	}

	if len(allIPs) == 0 {
		return nil, fmt.Errorf("failed to resolve %s from upstreams", host)
	}

	// 3. Store in Cache (Write Lock)
	d.mu.Lock()
	d.cache[host] = allIPs
	d.mu.Unlock()

	return allIPs, nil
}

